function ActivityMysteryAniRoot:StartPlayAni(drawType, callBack)
    self:InitBgShow()
    UIRaycastBlocker:AddCondition("ActivityMysteryAniRoot")
    self.aniCo = cs_coroutine.start(function()
        CfUtils.PlayAnimation(self.BoxNode,"ActivityMystery12002001_Box_Running")
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.35))
        local index = math.random(3)
        local toValue = SliderValue[index]
        CfUtils.DoTween(0.35,function(value)
            local value = toValue * value
            self.Slider.value = value
        end)
        CfUtils.SetActive(self.NorReward.gameObject,drawType == DrawType.One)
        CfUtils.SetActive(self.BigReward.gameObject, not (drawType == DrawType.One))
        
        local index = math.random(3)
        local str = drawType == 1 and "Ball" or "Big"
        CfUtils.SetActive(self[str..index].gameObject,true)
        
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.4))
        CfUtils.DoTween(0.35,function(value)
            local value = toValue - toValue * value
            self.Slider.value = value
        end)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
        UIRaycastBlocker:RemoveCondition("ActivityMysteryAniRoot")
        if callBack then
            callBack(Bind(self,self.InitAni))
        end
    end)
end

